function geometry(){
  const cx=targetX||w/2, targetY=h*.66, rx=Math.min(68,w*.18), cupY=h*.27;
  return {cx,targetY,rx,cupX,cupY};
}
function slopes(){
  return [
    {x1:w*.28,y1:h*.43,x2:w*.49,y2:h*.50},
    {x1:w*.57,y1:h*.55,x2:w*.78,y2:h*.47}
  ];
}
function drawSlopes(){
  slopes().forEach(s=>{
    const thickness=12;
    ctx.beginPath();ctx.moveTo(s.x1,s.y1);ctx.lineTo(s.x2,s.y2);ctx.lineTo(s.x2,s.y2+thickness);ctx.lineTo(s.x1,s.y1+thickness);ctx.closePath();
    ctx.fillStyle='#d9e5ee';ctx.fill();ctx.strokeStyle='#9fb5c7';ctx.lineWidth=2;ctx.stroke();
    ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(s.x1,s.y1+3);ctx.lineTo(s.x2,s.y2+3);ctx.stroke();
  });
}
function hitSlope(p,previousY){
  const ramps=slopes();
  for(let i=0;i<ramps.length;i++){
    const s=ramps[i];
    if(p.ignoreSlope===i){if(p.x<s.x1-5||p.x>s.x2+5)p.ignoreSlope=-1;else continue;}
    if(p.x<s.x1||p.x>s.x2)continue;
    const surface=s.y1+(s.y2-s.y1)*(p.x-s.x1)/(s.x2-s.x1);
    if(previousY+p.r<surface&&p.y+p.r>=surface){
      p.y=surface-p.r-1;p.vy=30;p.vx+=(s.x2>s.x1?105:-105);p.ignoreSlope=i;return true;
    }
  }
  return false;
}

