<body>
<main class="game">
  <header>
    <div class="brand"><div class="logo">💧</div><div><h1>Splash Landing</h1><p class="subtitle">An endless timing challenge</p></div></div>
    <div class="badge" id="levels">CUP LV 1 · TARGET LV 1</div>
  </header>
  <section class="stage" aria-label="Game area">
    <canvas id="game" aria-label="Tap the moving cup to pour water into the target" width="703" height="353"></canvas>
    <div class="hud"><div class="pill">CUP <strong id="remaining">100%</strong></div><div class="pill">ROUND <strong id="round">1</strong></div><div class="pill">TARGET <strong id="score">0%</strong></div></div>
    <div class="toast" id="toast">ROUND CLEAR!<small>Next round loading…</small></div>
  </section>
  <section class="bottom">
    <div class="control"><div class="control-head"><label>Ready, aim, splash!</label><span id="status">WAIT FOR IT</span></div><p class="hint">Tap the cup, press POUR, or hit Space. Guide each splash around the sloped ramps!</p></div>
    <div class="actions"><button class="pour" id="pour" type="button">💧 POUR</button><button class="reset" id="reset" type="button">↻</button></div>
  </section>
</main>
<script>
(() => {
  const canvas = document.querySelector('#game');
