    roundLabel.textContent=round;
    levelsLabel.textContent=`CUP LV ${cupLevel()} · TARGET LV ${targetLevel()}`;
    statusLabel.textContent=won?'ROUND CLEAR!':pourTime>0?'POURING!':cup<=0?'EMPTY':cooldown>0?'GET READY':'WAIT FOR IT';
    pourButton.disabled=won||cup<=0||pourTime>0||cooldown>0;
  }
  function resetRound(){angle=0;cup=100;caught=0;particles=[];spawnClock=0;pourTime=0;cooldown=0;won=false;clearTimer=0;cupX=46;cupDirection=1;toast.classList.remove('show');updateHUD();}
  function reset(){round=1;targetX=w/2;resetRound();}
  function startPour(){
    if(won||cup<=0||pourTime>0||cooldown>0)return;
    angle=58;pourTime=1.05;cooldown=1.35;spawnClock=0;updateHUD();
  }
  function tapCup(event){
    const r=canvas.getBoundingClientRect();const x=event.clientX-r.left;const y=event.clientY-r.top;const g=geometry();
