  }
  canvas.addEventListener('pointerdown',tapCup);
  pourButton.addEventListener('click',startPour);
  document.querySelector('#reset').addEventListener('click',reset);
  window.addEventListener('keydown',e=>{
    if(e.code==='Space'){e.preventDefault();startPour();}
