  function draw(){
    const dt=Math.min(.04,delta/1000);elapsed+=dt;
    const speed=Math.max(95,Math.min(150,w*.28))*(1+(cupLevel()-1)*.12);
    if(pourTime<=0&&!won){
      cupX+=cupDirection*speed*dt;
      if(cupX>=w-46){cupX=w-46;cupDirection=-1;}
      if(cupX<=46){cupX=46;cupDirection=1;}
    }
    if(pourTime>0&&!won){pourTime=Math.max(0,pourTime-dt);if(pourTime===0)angle=0;}
    if(cooldown>0)cooldown=Math.max(0,cooldown-dt);
    if(cupLevel()>=10){const lvl=targetLevel();const range=Math.min(w*.30,w*(.035+(lvl-1)*.023));targetX=w/2+Math.sin(elapsed*(.55+lvl*.12))*range;}else targetX=w/2;
    if(won&&clearTimer>0){clearTimer-=dt;if(clearTimer<=0){round++;resetRound();}}
    angle=pourTime>0&&!won?58:0;
    drawBackground();const g=geometry();
    const targetTop=g.targetY;
    // gentle ground shadow
    ctx.fillStyle='#f1f5f8';ctx.beginPath();ctx.ellipse(g.cx,targetTop+104,g.rx+32,9,0,0,Math.PI*2);ctx.fill();
    drawTarget(g.cx,targetTop,g.rx);drawSlopes();
    // Stream drops: only spawn when the cup is tipped far enough to pour.
    if(pourTime>0&&cup>0&&!won){spawnClock+=Math.min(40,delta);while(spawnClock>=72){spawnClock-=72;makeDrop(g);cup=Math.max(0,cup-1.6);}}
    for(let i=particles.length-1;i>=0;i--){
      const p=particles[i],previousY=p.y;p.age+=dt;p.vy+=420*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;
      hitSlope(p,previousY);
      if(p.y>=targetTop+41&&p.y<=targetTop+67){
        if(Math.abs(p.x-g.cx)<g.rx*.43){caught=Math.min(100,caught+2.3);}
        particles.splice(i,1);continue;
      }
      if(p.y>h*.91||p.x<-20||p.x>w+20){particles.splice(i,1);continue;}
      ctx.fillStyle='#43aef3';ctx.beginPath();ctx.ellipse(p.x,p.y,p.r*.78,p.r*1.25,0,0,Math.PI*2);ctx.fill();
      ctx.fillStyle='#c9efff';ctx.beginPath();ctx.arc(p.x-p.r*.25,p.y-p.r*.3,1.3,0,Math.PI*2);ctx.fill();
    }
    drawCup(g.cupX,g.cupY);
    // Aim marker gently indicates where the stream is headed while pouring.
    if(pourTime>0&&cup>0){const dropY=g.cupY+Math.sin(angle*Math.PI/180)*34-Math.cos(angle*Math.PI/180)*17;const fall=(targetTop+54-dropY);const flight=(-40+Math.sqrt(40*40+2*420*fall))/420;const aimX=g.cupX+Math.cos(angle*Math.PI/180)*34+Math.sin(angle*Math.PI/180)*18+24*flight;ctx.strokeStyle='#d3eaf8';ctx.setLineDash([4,6]);ctx.beginPath();ctx.moveTo(aimX,targetTop-7);ctx.lineTo(aimX,targetTop+4);ctx.stroke();ctx.setLineDash([]);}
    if(caught>=60&&!won){won=true;pourTime=0;clearTimer=1.5;toast.innerHTML=`ROUND ${round} CLEAR!<small>Next round loading…</small>`;toast.classList.add('show');}
    updateHUD();
  }
  let delta=16;
  function frame(t){delta=last?Math.min(40,t-last):16;last=t;draw();requestAnimationFrame(frame);}
  requestAnimationFrame(frame);
})();
</script>


